import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, RenderSurface } from 'claude-code'

import type {
  GitFile,
  GitSnapshot,
  Narration,
  NarrationPhase,
  StepView,
  TouchedFile,
  TurnRecord,
  TurnSteps,
  WorkbenchTab,
} from '../types'
import {
  ALERT,
  AMBER,
  CLAY,
  CLAY_MUTED,
  CLOUD,
  GLYPHS,
  ICONS,
  ICON_H,
  MARQUEE_H,
  DOTS_H,
  DOTS_W,
  SETTING_FIELDS,
  IDLE,
  OLIVE,
  SKY,
  STONE,
  ZERO,
  cellWidth,
  clip,
  clockTime,
  dayLabel,
  dayLog,
  detailOf,
  dotsSvg,
  duration,
  editedPath,
  errorOf,
  fmtTokens,
  groupByDay,
  iconWidth,
  isOwnConfigKey,
  labelOf,
  marqueeSvg,
  mergeNumstat,
  money,
  narratorConfig,
  oneLine,
  parseStatus,
  recordMeta,
  shortLabel,
  shortTool,
  splitPath,
  statusColor,
  stepTime,
  tokenTotal,
  toolColor,
  usageChart,
} from './lib'
import type { IconKind, NarratorConfig, SettingField } from './lib'
import { detectLang, setLang, tr } from './i18n'

// ── 状态 ──────────────────────────────────────────────────────────────────
const lineAtom = atom({ plugin: 'workbench', key: 'line' } as const, null as Narration | null)
const tickAtom = atom({ plugin: 'workbench', key: 'tick' } as const, 0)
const stepsAtom = atom({ plugin: 'workbench', key: 'steps' } as const, { request: '', items: [] } as TurnSteps)
const expandedAtom = atom({ plugin: 'workbench', key: 'expanded' } as const, null as string | null)
const tabAtom = atom({ plugin: 'workbench', key: 'tab' } as const, 'turn' as WorkbenchTab)
const touchedAtom = atom({ plugin: 'workbench', key: 'touched' } as const, [] as TouchedFile[])
const gitAtom = atom({ plugin: 'workbench', key: 'git' } as const, {
  isRepo: false,
  root: null,
  branch: null,
  files: [],
  isLoading: false,
  error: null,
  updatedAt: null,
} as GitSnapshot)
const historyAtom = atom({ plugin: 'workbench', key: 'history' } as const, [] as TurnRecord[])
const expandedTurnAtom = atom({ plugin: 'workbench', key: 'expandedTurn' } as const, null as string | null)
const legendAtom = atom({ plugin: 'workbench', key: 'legendOpen' } as const, false)
const narrationExpandedAtom = atom({ plugin: 'workbench', key: 'narrationExpanded' } as const, false)
const pendingSettingAtom = atom({ plugin: 'workbench', key: 'pendingSetting' } as const, null as { field: string; value: string } | null)
const confirmCompactAtom = atom({ plugin: 'workbench', key: 'confirmCompact' } as const, false)

const PANE = 'workbench'
const SETTINGS_PANE = 'workbench-settings'
const STORE_KEY = 'history'
const HISTORY_MAX = 300 // 跨会话最多留这么多轮
const MODEL = 'haiku'

const TICK_MS = 1000
// 横幅里的用时多久刷新一次。每次重绘都会替换按钮，刷得太勤点击会落空，所以放慢到 5 秒，
// 其余显示都只随真实变化（步骤、token、旁白）更新
const CLOCK_MS = 5000
const FLASH_MS = 1500 // token 增长后图标高亮多久
const TAIL = 800
const GIT_STALE_MS = 30_000
const MAX_ROWS = 40

const TABS: { id: WorkbenchTab; label: () => string }[] = [
  { id: 'turn', label: () => tr().tabTurn },
  { id: 'changes', label: () => tr().tabChanges },
  { id: 'history', label: () => tr().tabHistory },
]

// ── 这一轮的进度：模块变量，热重载时从头开始 ─────────────────────────────────
type Step = { tool: string; label: string; agent: boolean; ok: boolean | null; ms: number | null }
type Usage = { input_tokens: number; output_tokens: number; cache_read_input_tokens: number; cache_creation_input_tokens: number }

let request = ''
let steps: Step[] = []
let narratedAt = 0
let narratedSteps = 0
let isInFlight = false
let isWorking = false
let thinking = '' // 模型边想边写时流出来的文字，各留最近一段
let answering = ''
let material = 0
let narratedMaterial = 0
let isIntroPending = false // 刚发出请求，还没说第一句
let costAtStart: number | null = null
let turnFiles = new Set<string>() // 这一轮 Claude 改过的文件
let sessionId = ''
// 旁白配置：register 时从插件配置读入，配置一改模块就会重载
let config: NarratorConfig = narratorConfig({})

function feed(kind: 'thinking' | 'text', text: string) {
  if (kind === 'thinking') thinking = (thinking + text).slice(-TAIL)
  else answering = (answering + text).slice(-TAIL)
  material += text.length
}

const usageTotal = (u: Usage) => u.input_tokens + u.output_tokens + u.cache_read_input_tokens + u.cache_creation_input_tokens

// 实时旁白只需要最近几步、每步一短行；收尾总结看得多一些
const describe = (count = 10, width = 120) =>
  steps
    .slice(-count)
    .map((s, i) => {
      const m = tr()
      const state = s.ok === null ? m.stepRunning : s.ok ? m.stepDone(s.ms ?? 0) : m.stepFailed
      return `${i + 1}. ${s.agent ? m.subagent : ''}${s.tool}: ${clip(s.label, width) || m.noArgs} → ${state}`
    })
    .join('\n')

// ── 用量 ──────────────────────────────────────────────────────────────────
// 花费和上下文占用取自会话自己的账本（和状态栏、/cost 同一份），这次调用不花钱
async function refreshUsage($: EngineInterface) {
  const u = await $.session.usage()
  const usd = u.cost?.usd
  await update($, lineAtom, l =>
    l
      ? {
          ...l,
          costUsd: usd !== undefined && costAtStart !== null ? Math.max(0, usd - costAtStart) : l.costUsd,
          contextPercent: u.context.percent ?? l.contextPercent,
        }
      : l,
  )
}

// 每次写 $.state 都会让读它的界面重绘，重绘会替换按钮、让点击落空，所以一次模型响应只写一次：
// 先读账本，再把 token、花费、上下文合在一起写
async function addTurnUsage($: EngineInterface, u: Usage) {
  const now = Date.now()
  const at = (delta: number, prev: number) => (delta > 0 ? now : prev)
  const ledger = await $.session.usage().catch(() => null)
  const usd = ledger?.cost?.usd
  await update($, lineAtom, l =>
    l
      ? {
          ...l,
          costUsd: usd !== undefined && costAtStart !== null ? Math.max(0, usd - costAtStart) : l.costUsd,
          contextPercent: ledger?.context.percent ?? l.contextPercent,
          changedAt: {
            input: at(u.input_tokens, l.changedAt.input),
            output: at(u.output_tokens, l.changedAt.output),
            cacheRead: at(u.cache_read_input_tokens, l.changedAt.cacheRead),
            cacheWrite: at(u.cache_creation_input_tokens, l.changedAt.cacheWrite),
          },
          tokens: {
            input: l.tokens.input + u.input_tokens,
            output: l.tokens.output + u.output_tokens,
            cacheRead: l.tokens.cacheRead + u.cache_read_input_tokens,
            cacheWrite: l.tokens.cacheWrite + u.cache_creation_input_tokens,
          },
        }
      : l,
  )
}

async function addNarratorUsage($: EngineInterface, u: Usage | undefined) {
  if (!u) return
  await update($, lineAtom, l => (l ? { ...l, narratorTokens: l.narratorTokens + usageTotal(u) } : l))
}

// ── 旁白 ──────────────────────────────────────────────────────────────────
// 只在有新步骤或新素材、距上次够久、且没有请求在飞时才调用模型
async function narrateLive($: EngineInterface) {
  if (isInFlight || !isWorking || config.mode === 'off') return
  // 节能模式：只在工具调用时更新，不读思考和回复，也不在开头单独说一句
  const isFull = config.mode === 'full'
  const isIntro = isIntroPending && isFull
  const hasNew = isIntro || steps.length !== narratedSteps || (isFull && material - narratedMaterial >= config.materialStep)
  if (!hasNew) return
  if (!isIntro && Date.now() - narratedAt < config.minGapMs) return
  isInFlight = true
  isIntroPending = false
  narratedSteps = steps.length
  narratedMaterial = material
  narratedAt = Date.now()
  try {
    const r = await $.model.complete({
      model: MODEL,
      system: tr().systemLive,
      prompt: [
        `${tr().pRequest}\n${request.slice(0, 300)}`,
        steps.length ? `${tr().pRecentTools}\n${describe(6, 80)}` : tr().pNoTools,
        isFull && thinking ? `${tr().pThinking}\n${thinking.slice(-400)}` : '',
        isFull && answering ? `${tr().pAnswer}\n${answering.slice(-200)}` : '',
      ]
        .filter(Boolean)
        .join('\n\n'),
      maxTokens: 120,
      effort: 'low',
      timeoutMs: 10_000,
    })
    const text = r.isAnswered && isWorking ? oneLine(r.text) : ''
    const spent = r.usage ? usageTotal(r.usage) : 0
    if (text || spent) {
      await update($, lineAtom, l =>
        l ? { ...l, narratorTokens: l.narratorTokens + spent, text: text && l.phase === 'working' ? text : l.text } : l,
      )
    }
    if (text) await syncStatus($)
  } finally {
    isInFlight = false
  }
}

async function narrateDone($: EngineInterface, reply: string, isAborted: boolean) {
  const endedAt = Date.now()
  // 关闭了模型旁白，或没调用工具的简短问答，都不值得再花一次模型调用
  const isQuick = config.mode === 'off' || (steps.length === 0 && reply.length < 200)
  await update($, lineAtom, l =>
    l
      ? { ...l, phase: (isAborted ? 'interrupted' : 'done') as NarrationPhase, current: '', endedAt, isThinking: !isAborted && !isQuick }
      : l,
  )
  let text = ''
  if (isAborted) text = tr().aborted
  else if (isQuick) text = steps.length === 0 ? tr().answered : tr().doneSteps(steps.length)
  else {
    try {
      const r = await $.model.complete({
        model: MODEL,
        system: tr().systemDone,
        prompt:
          `${tr().pRequest}\n${request.slice(0, 600)}\n\n${tr().pSteps(steps.length)}\n${describe()}` +
          `\n\n${tr().pReply}\n${reply.slice(0, 1200)}`,
        maxTokens: 120,
        effort: 'low',
        timeoutMs: 15_000,
      })
      await addNarratorUsage($, r.usage)
      text = r.isAnswered ? oneLine(r.text) : ''
    } catch {
      // 模型没答上来就用兜底文案，下面照常收尾
    }
  }
  // 无论模型答没答、出没出错，都收起"更新中"，并把这一轮记进历史；最终花费和收尾文字一次写入
  const ledger = await $.session.usage().catch(() => null)
  const usd = ledger?.cost?.usd
  await update($, lineAtom, l =>
    l
      ? {
          ...l,
          text: text || tr().done,
          isThinking: false,
          costUsd: usd !== undefined && costAtStart !== null ? Math.max(0, usd - costAtStart) : l.costUsd,
          contextPercent: ledger?.context.percent ?? l.contextPercent,
        }
      : l,
  )
  await recordTurn($)
  await syncStatus($)
}

// ── 历史 ──────────────────────────────────────────────────────────────────
async function recordTurn($: EngineInterface) {
  const l = await read($, lineAtom)
  if (!l) return
  const cwd = await $.session.cwd().catch(() => '')
  const record: TurnRecord = {
    id: String(l.startedAt),
    sessionId,
    project: cwd.split('/').filter(Boolean).pop() ?? '',
    startedAt: l.startedAt,
    endedAt: l.endedAt ?? Date.now(),
    request: clip(request.replace(/\s+/g, ' ').trim(), 300),
    summary: l.text,
    phase: l.phase,
    steps: l.steps,
    errors: l.errors,
    tokens: l.tokens,
    narratorTokens: l.narratorTokens,
    costUsd: l.costUsd,
    files: [...turnFiles].map(p => splitPath(p).name).slice(0, 20),
  }
  const merge = (list: readonly TurnRecord[]) => [record, ...list.filter(r => r.id !== record.id)].slice(0, HISTORY_MAX)
  await update($, historyAtom, merge)
  const stored = await $.store.get(STORE_KEY).catch(() => undefined)
  await $.store.set(STORE_KEY, merge(Array.isArray(stored) ? (stored as TurnRecord[]) : [])).catch(() => undefined)
}

async function loadHistory($: EngineInterface) {
  const stored = await $.store.get(STORE_KEY).catch(() => undefined)
  if (!Array.isArray(stored)) return
  await update($, historyAtom, list => {
    const ids = new Set(list.map(r => r.id))
    return [...list, ...(stored as TurnRecord[]).filter(r => !ids.has(r.id))].sort((a, b) => b.startedAt - a.startedAt).slice(0, HISTORY_MAX)
  })
}

async function copyDayLog($: EngineInterface, surface: RenderSurface) {
  const log = dayLog(await read($, historyAtom))
  await copyText($, log, surface)
}

async function compactContext($: EngineInterface) {
  if (!(await read($, confirmCompactAtom))) {
    await update($, confirmCompactAtom, () => true)
    $.clock.after(5000, () => void update($, confirmCompactAtom, () => false))
    return
  }
  await update($, confirmCompactAtom, () => false)
  const r = await $.session.compact()
  $.ui.toast('skip' in r && r.skip ? tr().compactSkipped(r.skip) : tr().compacted)
  await refreshUsage($).catch(() => undefined)
}

// ── 状态栏：bandMode 为 status 时，旁白不占输入框上方，改显示在这里 ─────────────
async function syncStatus($: EngineInterface) {
  if (config.bandMode !== 'status') return
  const l = await read($, lineAtom)
  if (!l) return $.ui.status(undefined)
  const mark = l.phase === 'working' ? '●' : l.phase === 'done' ? '✓' : '✕'
  $.ui.status(tr().statusLine(mark, l.text, l.steps))
}

// 热重载会丢掉旧模块里还没跑完的旁白请求：新模块加载时把它留下的半截状态收尾
async function settleStale($: EngineInterface) {
  await update($, lineAtom, l => {
    if (!l || (!l.isThinking && l.phase !== 'working')) return l
    const isStaleLive = l.phase === 'working' || l.isThinking
    return {
      ...l,
      phase: l.phase === 'working' ? ('done' as NarrationPhase) : l.phase,
      text: isStaleLive ? tr().done : l.text,
      current: '',
      endedAt: l.endedAt ?? Date.now(),
      isThinking: false,
    }
  })
}

// ── 改动：git 工作区快照 ────────────────────────────────────────────────────
async function git($: EngineInterface, cwd: string, args: string[]): Promise<string | null> {
  try {
    const { exitCode, stdout } = await $.process.run(['git', ...args], { cwd, timeoutMs: 15_000 })
    return exitCode === 0 ? stdout : null
  } catch {
    return null
  }
}

async function refreshGit($: EngineInterface) {
  const cwd = await $.session.cwd()
  await update($, gitAtom, g => ({ ...g, isLoading: true, error: null }))
  const root = (await git($, cwd, ['rev-parse', '--show-toplevel']))?.trim()
  if (!root) {
    await update($, gitAtom, () => ({ isRepo: false, root: null, branch: null, files: [], isLoading: false, error: null, updatedAt: Date.now() }))
    return
  }
  const [branch, status, numstat] = await Promise.all([
    git($, root, ['rev-parse', '--abbrev-ref', 'HEAD']),
    git($, root, ['status', '--porcelain=v1']),
    git($, root, ['diff', '--numstat', 'HEAD']).then(out => out ?? git($, root, ['diff', '--numstat'])),
  ])
  if (status === null) {
    await update($, gitAtom, g => ({ ...g, isLoading: false, error: tr().gitStatusFailed }))
    return
  }
  const files = mergeNumstat(parseStatus(status), numstat ?? '')
  await update($, gitAtom, () => ({
    isRepo: true,
    root,
    branch: branch?.trim() ?? null,
    files,
    isLoading: false,
    error: null,
    updatedAt: Date.now(),
  }))
}

// ── 本轮步骤的快捷操作 ─────────────────────────────────────────────────────
async function copyText($: EngineInterface, text: string, surface: RenderSurface) {
  const r = await $.ui.copy({ text, surface })
  $.ui.toast(r.isCopied ? tr().copied : tr().copyFailed('reason' in r ? r.reason : tr().unknownReason))
}

// ── 设置 ──────────────────────────────────────────────────────────────────
async function openSettings($: EngineInterface) {
  // 请求键盘焦点：有的界面第一下点击只是激活面板，拿到焦点后第一下就能点中
  await $.ui.open({ id: SETTINGS_PANE, title: tr().settingsTitle, focus: true })
}

// 和 /config 菜单走同一条路：$.config.set 写进设置，插件随后带着新值重载
// 点下去先把高亮挪过去（pendingSetting），保存成功后插件会带着新值重载，
// 重载时 session.start 再清掉它；保存期间同一项的重复点击直接忽略
async function saveSetting($: EngineInterface, field: SettingField, value: string | number) {
  if ((await read($, pendingSettingAtom))?.field === field) return
  await update($, pendingSettingAtom, () => ({ field, value: String(value) }))
  const fail = async (message: string) => {
    await update($, pendingSettingAtom, () => null)
    $.ui.toast(message)
  }
  const row = (await $.config.list()).find(r => isOwnConfigKey(r.key, field))
  if (!row) return fail(tr().settingMissing)
  if (row.isLocked) return fail(tr().settingLocked)
  const r = await $.config.set({ key: row.key, value })
  if ('deny' in r && r.deny) return fail(tr().settingFailed(r.deny))
  $.ui.toast(tr().settingSaved)
  // 万一没有触发重载（比如值其实没变），几秒后自己收起「保存中」
  $.clock.after(4000, () => void update($, pendingSettingAtom, p => (p?.field === field ? null : p)))
}

// ── 面板 ──────────────────────────────────────────────────────────────────
async function openPane($: EngineInterface, tab: WorkbenchTab) {
  await update($, tabAtom, () => tab)
  if (tab === 'changes' && Date.now() - ((await read($, gitAtom)).updatedAt ?? 0) > GIT_STALE_MS) void refreshGit($)
  await $.ui.open({ id: PANE, title: tr().paneTitle })
}

async function openLastTab($: EngineInterface) {
  await openPane($, await read($, tabAtom))
}

async function switchTab($: EngineInterface, tab: WorkbenchTab) {
  await update($, tabAtom, () => tab)
  if (tab === 'changes' && Date.now() - ((await read($, gitAtom)).updatedAt ?? 0) > GIT_STALE_MS) void refreshGit($)
}

export const register: Register = (on, options) => {
  config = narratorConfig(options)
  setLang(config.language === 'auto' ? 'en' : config.language) // auto 在 session.start 里再按设置和系统语言判断

  on('session.start', async ($, e, next) => {
    const started = await next(e)
    await settleStale($)
    await update($, pendingSettingAtom, () => null)
    if (config.language === 'auto') {
      const settings = (await $.settings.read().catch(() => ({}))) as Record<string, unknown>
      const locale = (await $.env.get('LC_ALL').catch(() => undefined)) || (await $.env.get('LANG').catch(() => undefined))
      setLang(detectLang(settings['language'], locale))
    }
    await $.command.register({ name: 'workbench', description: tr().cmdDescription })
    sessionId = await $.session.id().catch(() => '')
    void loadHistory($)
    if (config.bandMode !== 'status') $.ui.status(undefined)
    void refreshGit($)

    // 只为让用时走起来，工作中每 5 秒一次；空闲时完全不重绘
    $.clock.every(CLOCK_MS, () => {
      if (isWorking) void update($, tickAtom, n => n + 1)
    })
    // 每秒看一次要不要生成新旁白
    $.clock.every(TICK_MS, () => {
      if (isWorking) void narrateLive($)
    })
    return started
  })

  on('command.run', { command: 'workbench' }, async ($, e) => {
    if (/^(settings|config|设置)$/i.test(e.args.trim())) {
      await openSettings($)
      return { text: tr().settingsTitle }
    }
    await openPane($, await read($, tabAtom))
    return { text: tr().cmdOpened }
  })

  on('prompt.submit', async ($, e, next) => {
    request = e.text
    steps = []
    narratedSteps = 0
    narratedAt = 0
    thinking = ''
    answering = ''
    material = 0
    narratedMaterial = 0
    isIntroPending = true
    isWorking = true
    turnFiles = new Set()
    await update($, stepsAtom, () => ({ request: e.text.replace(/\s+/g, ' ').slice(0, 200), items: [] }))
    await update($, expandedAtom, () => null)
    await update($, narrationExpandedAtom, () => false) // 新一轮的旁白先收起
    costAtStart = await $.session.usage().then(
      u => u.cost?.usd ?? null,
      () => null,
    )
    await update($, lineAtom, () => ({
      phase: 'working' as NarrationPhase,
      text: tr().understanding,
      current: '',
      steps: 0,
      errors: 0,
      startedAt: Date.now(),
      endedAt: null,
      isThinking: false,
      tokens: ZERO,
      narratorTokens: 0,
      costUsd: costAtStart === null ? null : 0,
      contextPercent: null,
      changedAt: ZERO,
    }))
    await syncStatus($)
    return next(e)
  })

  on('turn.step', async function* ($, e, next) {
    for await (const chunk of next(e)) {
      if (isWorking) {
        if (chunk.kind === 'thinking' || chunk.kind === 'text') feed(chunk.kind, chunk.text)
        if (chunk.kind === 'stop' && chunk.usage) void addTurnUsage($, chunk.usage)
      }
      yield chunk
    }
  })

  on('tool.call', async ($, e, next) => {
    const args = e as unknown as Record<string, unknown>
    const step: Step = { tool: e.tool, label: labelOf(args), agent: e.agentId !== undefined, ok: null, ms: null }
    const startedAt = Date.now()
    const id = e.tool_use_id ?? `${e.tool}-${startedAt}`
    steps.push(step)
    const view: StepView = { id, tool: step.tool, label: step.label, detail: detailOf(args), agent: step.agent, ok: null, startedAt, ms: null, error: null }
    await update($, stepsAtom, s => ({ ...s, items: [...s.items, view].slice(-200) }))
    const current = `${shortTool(step.tool)}${step.label ? ` · ${shortLabel(step.label)}` : ''}`
    await update($, lineAtom, l =>
      l ? { ...l, current, steps: steps.length, text: config.mode === 'off' && isWorking ? tr().running(current) : l.text } : l,
    )
    await syncStatus($)

    let ok = false
    let error: string | null = tr().interrupted
    try {
      const ran = await next(e)
      ok = ran.deny === undefined && ran.isError !== true
      error = errorOf(ran)
      return ran
    } finally {
      step.ok = ok
      step.ms = Date.now() - startedAt
      const ms = step.ms
      if (!ok) await update($, lineAtom, l => (l ? { ...l, errors: l.errors + 1 } : l))
      await update($, stepsAtom, s => ({
        ...s,
        items: s.items.map(v => (v.id === id ? { ...v, ok, ms, error: ok ? null : error } : v)),
      }))
      // 记下 Claude 改过的文件，改动页据此标出"Claude 改的"
      const path = ok ? editedPath(e.tool, args) : null
      if (path) {
        turnFiles.add(path)
        const now = Date.now()
        await update($, touchedAtom, list => {
          const hit = list.find(f => f.path === path)
          const rest = list.filter(f => f.path !== path)
          return [{ path, edits: (hit?.edits ?? 0) + 1, lastAt: now }, ...rest].slice(0, 200)
        })
      }
    }
  })

  on('turn.complete', async ($, e, next) => {
    const done = await next(e)
    if (e.agentId !== undefined) return done
    if (isWorking) {
      isWorking = false
      void narrateDone($, e.answer, e.isAborted)
    }
    // 一轮结束：刷新改动
    void refreshGit($)
    return done
  })

  // ── 输入框上方的旁白条 ──────────────────────────────────────────────────
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const line = await read($, lineAtom)
    if (config.bandMode !== 'band' || e.props.hasSurvey || !line) return next(e)
    await read($, tickAtom) // 订阅慢速时钟，让用时走起来
    const isLegendOpen = await read($, legendAtom)
    const isExpanded = await read($, narrationExpandedAtom)
    const gitState = await read($, gitAtom)

    const resolved = $.ui.resolve(e)
    const { Box, Text, Button } = resolved
    // 终端的组件表里也有 Svg，但只会显示替代文字，所以按表面判断：终端走 Unicode 符号和纯文本
    const Svg = e.surface !== 'terminal' && 'Svg' in resolved ? resolved.Svg : null
    const now = Date.now()
    const isWorkingNow = line.phase === 'working'
    const elapsed = duration((line.endedAt ?? now) - line.startedAt)
    const color = isWorkingNow ? CLAY : line.phase === 'done' ? CLAY_MUTED : STONE

    const t = line.tokens
    const hasTokens = t.input + t.output + t.cacheRead + t.cacheWrite > 0
    const prompt = t.input + t.cacheRead + t.cacheWrite
    const hitRate = prompt > 0 ? Math.round((t.cacheRead / prompt) * 100) : null
    const ctx = line.contextPercent
    const ctxColor = ctx === null ? CLOUD : ctx >= 85 ? ALERT : ctx >= 60 ? AMBER : CLAY_MUTED
    const ctxFilled = ctx === null ? 0 : Math.max(0, Math.min(10, Math.round(ctx / 10)))
    const rule = '─'.repeat(Math.max(10, Math.min(240, e.props.bodyColumns - 2)))
    const isFresh = (at: number) => isWorkingNow && now - at < FLASH_MS

    // 第一行旁白：按 narrationOverflow 决定放不下时怎么办
    const overflow = config.overflow === 'scroll' && !Svg ? 'wrap' : config.overflow
    const marqueeW = Math.max(200, Math.min(1400, (e.props.bodyColumns - 10) * 8))
    const narration =
      overflow === 'scroll' && Svg ? (
        <Box flexGrow={1} flexShrink={1} minWidth={0} overflow="hidden">
          <Svg source={marqueeSvg(line.text, color, isWorkingNow, marqueeW)} alt={line.text} width={marqueeW} height={MARQUEE_H} />
        </Box>
      ) : overflow === 'wrap' || isExpanded ? (
        <Box flexGrow={1} flexShrink={1} minWidth={0}>
          <Text bold={isWorkingNow} color={color} wrap="wrap">
            {line.text}
          </Text>
        </Box>
      ) : (
        // 省略：单行截断；放不下时旁边有「全文」按钮，点了才展开
        <Box flexGrow={1} flexShrink={1} minWidth={0}>
          <Text bold={isWorkingNow} color={color} wrap="truncate-end">
            {line.text}
          </Text>
        </Box>
      )
    // 估算放不下：按格数比较，右侧还有状态格和按钮。Desktop 用的是比例字体，格数和实际宽度对不准，
    // 门槛放宽到六成：宁可在刚好放得下时多显示一个「全文」，也不要截断了却没有入口
    const isLong = cellWidth(line.text) > (e.props.bodyColumns - 16) * 0.6
    const expandToggle =
      overflow === 'truncate' && (isLong || isExpanded) ? (
        <Box key="narration-toggle" flexShrink={0}>
          <Button
            key="narration-expand"
            plain
            dimColor
            label={isExpanded ? tr().collapseNarration : tr().expandNarration}
            hover={{ underline: true, dimColor: false }}
            onPress={() => void update($, narrationExpandedAtom, v => !v)}
          />
        </Box>
      ) : null

    // 图标的含义：悬停弹出太容易误触（引擎的悬停没有延迟），改成点 ⓘ 才在下方展开图例
    const icon = (kind: IconKind, c: string) =>
      Svg ? (
        <Svg source={ICONS[kind](c)} alt={tr().alt[kind]} width={iconWidth(kind)} height={ICON_H} />
      ) : (
        <Text color={c}>{GLYPHS[kind]}</Text>
      )
    const legend = (
      <Box flexDirection="row" flexWrap="wrap" columnGap={2}>
        {(['input', 'output', 'cacheRead', 'cacheWrite', 'narrator', 'hit', 'cost', 'context'] as const).map(kind => (
          <Box flexDirection="row" alignItems="center" gap={1}>
            {icon(kind, kind === 'input' ? CLAY : kind === 'output' ? SKY : kind === 'cacheRead' ? OLIVE : kind === 'cacheWrite' ? AMBER : kind === 'hit' || kind === 'context' ? CLAY_MUTED : kind === 'cost' ? OLIVE : IDLE)}
            <Text dimColor>{tr().legend[kind]}</Text>
          </Box>
        ))}
      </Box>
    )

    // 一个指标：图标 + 加粗数值；图标颜色表示类别，刚增长时换成高亮色、数值同色
    const stat = (kind: IconKind, value: string, tint: string, isLit = false) => {
      const c = isLit ? tint : kind === 'input' || kind === 'output' ? IDLE : tint
      return (
        <Box flexDirection="row" alignItems="center" gap={1}>
          {icon(kind, c)}
          <Text bold color={isLit ? tint : undefined}>
            {value}
          </Text>
        </Box>
      )
    }

    return (
      <Box flexDirection="column" paddingX={1}>
        {/* 旁白占满左侧，状态钉在右侧固定宽度的格子里：文字长短变化不会挪动它 */}
        <Box flexDirection="row" gap={1}>
          {narration}
          {expandToggle}
          <Box width={6} flexShrink={0} justifyContent="flex-end">
            {isWorkingNow ? (
              Svg ? (
                <Svg source={dotsSvg(CLAY, CLOUD)} alt={tr().working} width={DOTS_W} height={DOTS_H} />
              ) : (
                <Text color={CLAY}>● ● ●</Text>
              )
            ) : (
              <Text bold color={color}>
                {line.phase === 'done' ? '✓' : '✕'}
              </Text>
            )}
          </Box>
        </Box>

        <Text color={CLOUD} dimColor wrap="truncate-end">
          {rule}
        </Text>

        {/* 进度行：左边是信息，右边钉着两个入口按钮（工作台、设置），左边再长也挤不走它们 */}
        <Box flexDirection="row" alignItems="center" gap={2}>
          <Box flexGrow={1} flexShrink={1} minWidth={0} flexDirection="row" flexWrap="wrap" columnGap={2}>
            <Text>{tr().bandSteps(isWorkingNow, line.steps)}</Text>
            <Text>
              <Text dimColor>{tr().bandTime}</Text>
              <Text bold>{elapsed}</Text>
            </Text>
            {line.errors > 0 && (
              <Box key="open-errors">
                <Button
                  key="errors"
                  plain
                  label={tr().bandFailures(line.errors)}
                  hover={{ underline: true }}
                  onPress={() => void openPane($, 'turn')}
                />
              </Box>
            )}
            {gitState.files.length > 0 && (
              <Box key="open-changes">
                <Button
                  key="changes"
                  plain
                  label={tr().bandChanges(gitState.files.length)}
                  hover={{ underline: true, color: CLAY }}
                  onPress={() => void openPane($, 'changes')}
                />
              </Box>
            )}
            {line.current && (
              <Text dimColor wrap="truncate-end">
                ▸ {line.current}
              </Text>
            )}
          </Box>
          <Box flexShrink={0} flexDirection="row" alignItems="center" gap={1}>
            <Button key="open-workbench" label={tr().openWorkbench} onPress={() => void openLastTab($)} />
            <Button key="band-open-settings" label={tr().settingsButton} onPress={() => void openSettings($)} />
          </Box>
        </Box>

        {hasTokens && (
          <Box flexDirection="row" flexWrap="wrap" columnGap={2}>
            {stat('input', fmtTokens(t.input), CLAY, isFresh(line.changedAt.input))}
            {stat('output', fmtTokens(t.output), SKY, isFresh(line.changedAt.output))}
            {stat('cacheRead', fmtTokens(t.cacheRead), OLIVE)}
            {stat('cacheWrite', fmtTokens(t.cacheWrite), AMBER)}
            {line.narratorTokens > 0 && stat('narrator', fmtTokens(line.narratorTokens), IDLE)}
            <Text dimColor>│</Text>
            {hitRate !== null && stat('hit', `${hitRate}%`, CLAY_MUTED)}
            {line.costUsd !== null && stat('cost', line.costUsd.toFixed(line.costUsd < 1 ? 3 : 2), OLIVE)}
            {ctx !== null && (
              <Box flexDirection="row" alignItems="center" gap={1}>
                {Svg ? (
                  <Svg source={ICONS.context(ctxColor)} alt={tr().alt.context} width={ICON_H} height={ICON_H} />
                ) : (
                  <Text color={ctxColor}>{GLYPHS.context}</Text>
                )}
                <Text>
                  <Text color={ctxColor}>{'▰'.repeat(ctxFilled)}</Text>
                  <Text color={IDLE}>{'▱'.repeat(10 - ctxFilled)}</Text>
                  <Text bold color={ctxColor}>
                    {' '}
                    {Math.round(ctx)}%
                  </Text>
                </Text>
              </Box>
            )}
            <Box key="legend-toggle-box">
              <Button
                key="legend-toggle"
                plain
                dimColor={!isLegendOpen}
                label={isLegendOpen ? tr().legendHide : tr().legendShow}
                hover={{ underline: true, dimColor: false }}
                onPress={() => void update($, legendAtom, v => !v)}
              />
            </Box>
          </Box>
        )}
        {hasTokens && isLegendOpen && legend}
      </Box>
    )
  })

  // ── 工作台面板：本轮 / 改动 ──────────────────────────────────────
  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text, Button } = $.ui.resolve(e)
    const tab = await read($, tabAtom)
    const stepsState = await read($, stepsAtom)
    const gitState = await read($, gitAtom)
    const line = await read($, lineAtom)
    const now = Date.now()

    const counts: Record<WorkbenchTab, number> = {
      turn: stepsState.items.length,
      changes: gitState.files.length,
      history: (await read($, historyAtom)).filter(r => r.sessionId === sessionId).length,
    }

    const header = (
      <Box flexDirection="row" gap={1} flexWrap="wrap" alignItems="center">
        {TABS.map(t => (
          <Button
            key={`tab-${t.id}`}
            label={counts[t.id] ? `${t.label()} ${counts[t.id]}` : t.label()}
            variant={t.id === tab ? 'primary' : 'secondary'}
            onPress={() => void switchTab($, t.id)}
          />
        ))}
        <Box flexGrow={1} />
        <Box key="settings-link">
          <Button key="open-settings" plain label={tr().settingsButton} hover={{ underline: true, color: CLAY }} onPress={() => void openSettings($)} />
        </Box>
      </Box>
    )

    // ── 本轮 ──
    const turnView = async () => {
      const expanded = await read($, expandedAtom)
      const { request: req, items } = stepsState
      const isWorkingNow = line?.phase === 'working'
      const okCount = items.filter(v => v.ok === true).length
      const failCount = items.filter(v => v.ok === false).length
      const elapsed = line ? duration((line.endedAt ?? now) - line.startedAt) : ''
      return (
        <Box flexDirection="column" gap={1}>
          <Box flexDirection="column">
            <Text bold>{isWorkingNow ? tr().turnTitle : tr().lastTurnTitle}</Text>
            <Text dimColor wrap="truncate-end">
              {[tr().nSteps(items.length), okCount ? tr().nOk(okCount) : null, failCount ? tr().nFailed(failCount) : null, elapsed ? tr().timeSpent(elapsed) : null]
                .filter(Boolean)
                .join(' · ')}
            </Text>
            {req && (
              <Text color={CLOUD} wrap="truncate-end">
                「{req}」
              </Text>
            )}
          </Box>
          {items.length === 0 && <Text dimColor>{tr().noSteps}</Text>}
          <Box flexDirection="column">
            {items.map((v, i) => {
              const isOpen = expanded === v.id
              const mark = v.ok === null ? '●' : v.ok ? '✓' : '✕'
              const markColor = v.ok === null ? CLAY : v.ok ? OLIVE : ALERT
              const ms = v.ms ?? now - v.startedAt
              return (
                <Box key={`step-${v.id}`} flexDirection="column" marginBottom={isOpen ? 1 : 0}>
                  <Box flexDirection="row" gap={1} alignItems="center">
                    <Box width={2} flexShrink={0}>
                      <Text bold color={markColor}>
                        {mark}
                      </Text>
                    </Box>
                    <Box width={3} flexShrink={0}>
                      <Text dimColor>{i + 1}</Text>
                    </Box>
                    <Box flexShrink={0}>
                      <Text bold color={toolColor(v.tool)}>
                        {v.agent ? '↳ ' : ''}
                        {shortTool(v.tool)}
                      </Text>
                    </Box>
                    <Box flexGrow={1} flexShrink={1} minWidth={0} overflow="hidden">
                      <Button
                        key={`toggle-${v.id}`}
                        plain
                        dimColor={!isOpen}
                        label={`${isOpen ? '▾' : '▸'} ${v.label ? shortLabel(v.label) : tr().noArgs}`}
                        hover={{ underline: true, dimColor: false }}
                        onPress={() => void update($, expandedAtom, cur => (cur === v.id ? null : v.id))}
                      />
                    </Box>
                    <Box flexShrink={0}>
                      <Text color={v.ok === null ? CLAY : undefined} dimColor={v.ok !== null}>
                        {v.ok === null ? `${duration(ms)}…` : stepTime(ms)}
                      </Text>
                    </Box>
                  </Box>
                  {isOpen && (
                    <Box flexDirection="column" paddingLeft={6} marginTop={1} gap={1}>
                      <Text wrap="wrap">{v.detail || v.label || tr().noArgs}</Text>
                      {v.error && (
                        <Text color={ALERT} wrap="wrap">
                          {v.error}
                        </Text>
                      )}
                      {v.detail && (
                        <Box flexDirection="row" gap={1} flexWrap="wrap">
                          {v.ok === false && (
                            <Button
                              key={`retry-${v.id}`}
                              variant="primary"
                              label={tr().retry}
                              onPress={() => void $.prompt.submit({ text: tr().retryPrompt(v.tool, v.detail, v.error) })}
                            />
                          )}
                          <Button key={`copy-${v.id}`} label={tr().copy} onPress={() => void copyText($, v.detail, e.surface)} />
                          <Button
                            key={`fill-${v.id}`}
                            label={tr().fill}
                            onPress={() => void $.prompt.fill({ text: v.detail, mode: 'replace' })}
                          />
                        </Box>
                      )}
                    </Box>
                  )}
                </Box>
              )
            })}
          </Box>
        </Box>
      )
    }

    // ── 改动 ──
    const changesView = async () => {
      const touched = await read($, touchedAtom)
      const root = gitState.root
      const rel = (abs: string) => (root && abs.startsWith(`${root}/`) ? abs.slice(root.length + 1) : abs)
      const touchedRel = new Map(touched.map(f => [rel(f.path), f]))
      const files = gitState.files
      const added = files.reduce((s, f) => s + (f.added ?? 0), 0)
      const removed = files.reduce((s, f) => s + (f.removed ?? 0), 0)
      const byClaude = files.filter(f => touchedRel.has(f.path))
      const others = files.filter(f => !touchedRel.has(f.path))
      // Claude 改过、但已经不在工作区改动里的（提交了或改回去了）
      const settled = touched.filter(f => !files.some(g => g.path === rel(f.path)))

      const fileRow = (f: GitFile) => {
        const { dir, name } = splitPath(f.path)
        const mine = touchedRel.get(f.path)
        return (
          <Box key={`file-${f.path}`} flexDirection="row" gap={1} alignItems="center">
            <Box width={2} flexShrink={0}>
              <Text bold color={statusColor(f.status)}>
                {tr().statusLabel(f.status)}
              </Text>
            </Box>
            <Box flexGrow={1} flexShrink={1} minWidth={0} overflow="hidden">
              <Button
                key={`mention-${f.path}`}
                plain
                label={`${clip(dir, 40)}${name}`}
                hover={{ underline: true, color: CLAY }}
                onPress={() => void $.prompt.fill({ text: `@${f.path} `, mode: 'append' })}
              />
            </Box>
            {mine && (
              <Box flexShrink={0}>
                <Text color={CLAY}>Claude ×{mine.edits}</Text>
              </Box>
            )}
            <Box flexShrink={0}>
              <Text>
                {f.added !== null && <Text color={OLIVE}>+{f.added}</Text>}
                {f.removed !== null && <Text color={ALERT}> −{f.removed}</Text>}
                {f.status === '??' && <Text dimColor>{tr().newFile}</Text>}
              </Text>
            </Box>
          </Box>
        )
      }

      if (!gitState.isRepo) {
        return (
          <Box flexDirection="column" gap={1}>
            <Text dimColor>{gitState.isLoading ? tr().loading : tr().notRepo}</Text>
            {touched.length > 0 && <Text>{tr().touchedCount(touched.length)}</Text>}
          </Box>
        )
      }

      return (
        <Box flexDirection="column" gap={1}>
          <Box flexDirection="row" gap={1} alignItems="center">
            <Box flexGrow={1} minWidth={0}>
              <Text wrap="truncate-end">
                <Text color={SKY}>⎇ </Text>
                <Text bold>{gitState.branch ?? tr().noBranch}</Text>
                <Text dimColor>
                  {'  '}
                  {tr().nFiles(files.length)}
                </Text>
                {added > 0 && <Text color={OLIVE}> +{added}</Text>}
                {removed > 0 && <Text color={ALERT}> −{removed}</Text>}
              </Text>
            </Box>
            <Text dimColor>{gitState.isLoading ? tr().refreshing : gitState.updatedAt ? tr().updatedAt(clockTime(gitState.updatedAt)) : ''}</Text>
            <Button key="git-refresh" label={tr().refresh} onPress={() => void refreshGit($)} />
          </Box>
          {gitState.error && <Text color={ALERT}>{gitState.error}</Text>}

          <Box flexDirection="row" gap={1} flexWrap="wrap">
            <Button
              key="summarize"
              label={tr().summarize}
              onPress={() => void $.prompt.submit({ text: tr().summaryPrompt(files.map(f => f.path)) })}
            />
            <Button key="commit-msg" label={tr().commitMsg} onPress={() => void $.prompt.submit({ text: tr().commitPrompt })} />
          </Box>

          {files.length === 0 && <Text dimColor>{tr().clean}</Text>}

          {byClaude.length > 0 && (
            <Box flexDirection="column">
              <Text bold color={CLAY}>
                {tr().byClaude(byClaude.length)}
              </Text>
              {byClaude.slice(0, MAX_ROWS).map(fileRow)}
            </Box>
          )}

          {others.length > 0 && (
            <Box flexDirection="column">
              <Text bold>
                {byClaude.length > 0 ? tr().otherChanges(others.length) : tr().workingChanges(others.length)}
              </Text>
              {others.slice(0, MAX_ROWS).map(fileRow)}
              {others.length > MAX_ROWS && <Text dimColor>{tr().moreFiles(others.length - MAX_ROWS)}</Text>}
            </Box>
          )}

          {settled.length > 0 && (
            <Text dimColor wrap="truncate-end">
              {tr().settled(settled.length, settled.map(f => splitPath(rel(f.path)).name).slice(0, 6).join(tr().listSep))}
            </Text>
          )}
          <Text dimColor>{tr().mentionHint}</Text>
        </Box>
      )
    }

    // ── 历史 ──
    const historyView = async () => {
      const history = await read($, historyAtom)
      const expanded = await read($, expandedTurnAtom)
      const confirm = await read($, confirmCompactAtom)
      const mine = history.filter(r => r.sessionId === sessionId)
      const cost = mine.reduce((s, r) => s + (r.costUsd ?? 0), 0)
      const hasCost = mine.some(r => r.costUsd !== null)
      const tokens = mine.reduce((s, r) => s + tokenTotal(r.tokens), 0)
      const spent = mine.reduce((s, r) => s + (r.endedAt - r.startedAt), 0)
      const ctx = line?.contextPercent ?? null
      const ctxColor = ctx === null ? CLOUD : ctx >= 85 ? ALERT : ctx >= 60 ? AMBER : CLAY_MUTED
      const ctxFilled = ctx === null ? 0 : Math.max(0, Math.min(10, Math.round(ctx / 10)))
      const resolved = $.ui.resolve(e)
      const Svg = e.surface !== 'terminal' && 'Svg' in resolved ? resolved.Svg : null
      const chartW = Math.max(240, Math.min(720, e.props.bodyColumns * 7))

      return (
        <Box flexDirection="column" gap={1}>
          <Box flexDirection="column">
            <Text bold>{tr().session}</Text>
            <Text wrap="truncate-end">
              <Text bold>{mine.length}</Text>
              <Text dimColor>{tr().turnsTime}</Text>
              <Text bold>{duration(spent)}</Text>
              <Text dimColor>{tr().tokensLabel}</Text>
              <Text bold>{fmtTokens(tokens)}</Text>
              {hasCost && <Text dimColor>{tr().costLabel}</Text>}
              {hasCost && <Text bold>{money(cost)}</Text>}
            </Text>
            {ctx !== null && (
              <Box flexDirection="row" gap={1} alignItems="center">
                <Text>
                  <Text dimColor>{tr().context}</Text>
                  <Text color={ctxColor}>{'▰'.repeat(ctxFilled)}</Text>
                  <Text color={IDLE}>{'▱'.repeat(10 - ctxFilled)}</Text>
                  <Text bold color={ctxColor}>
                    {' '}
                    {Math.round(ctx)}%
                  </Text>
                </Text>
                {ctx >= 50 && (
                  <Button
                    key="compact"
                    variant={confirm ? 'primary' : 'secondary'}
                    label={confirm ? tr().compactConfirm : tr().compact}
                    onPress={() => void compactContext($)}
                  />
                )}
              </Box>
            )}
          </Box>

          {history.length > 1 && Svg && (
            <Svg source={usageChart(history, chartW, 64)} alt={tr().chartAlt(Math.min(24, history.length))} width={chartW} height={64} />
          )}

          <Box flexDirection="row" gap={1} flexWrap="wrap">
            <Button key="copy-day" label={tr().copyDay} onPress={() => void copyDayLog($, e.surface)} />
          </Box>

          {history.length === 0 && <Text dimColor>{tr().noHistory}</Text>}

          {groupByDay(history).map(group => (
            <Box key={`day-${group.label}`} flexDirection="column">
              <Text bold color={CLAY_MUTED}>
                {tr().dayTurns(group.label, group.items.length)}
              </Text>
              {group.items.slice(0, 50).map(r => {
                const isOpen = expanded === r.id
                const mark = r.phase === 'interrupted' ? '✕' : r.errors > 0 ? '!' : '✓'
                const markColor = r.phase === 'interrupted' ? STONE : r.errors > 0 ? AMBER : OLIVE
                return (
                  <Box key={`turn-${r.id}`} flexDirection="column" marginBottom={isOpen ? 1 : 0}>
                    <Box flexDirection="row" gap={1} alignItems="center">
                      <Box width={2} flexShrink={0}>
                        <Text bold color={markColor}>
                          {mark}
                        </Text>
                      </Box>
                      <Box width={6} flexShrink={0}>
                        <Text dimColor>{clockTime(r.startedAt)}</Text>
                      </Box>
                      <Box flexGrow={1} flexShrink={1} minWidth={0} overflow="hidden">
                        <Button
                          key={`turn-toggle-${r.id}`}
                          plain
                          label={`${isOpen ? '▾' : '▸'} ${r.summary}`}
                          hover={{ underline: true, color: CLAY }}
                          onPress={() => void update($, expandedTurnAtom, cur => (cur === r.id ? null : r.id))}
                        />
                      </Box>
                      <Box flexShrink={0}>
                        <Text dimColor>{recordMeta(r)}</Text>
                      </Box>
                    </Box>
                    {isOpen && (
                      <Box flexDirection="column" paddingLeft={9} marginTop={1}>
                        <Text color={CLOUD} wrap="wrap">
                          「{r.request}」
                        </Text>
                        <Text dimColor wrap="wrap">
                          {[
                            r.project ? tr().project(r.project) : null,
                            r.sessionId === sessionId ? tr().thisSession : tr().otherSession(dayLabel(r.startedAt)),
                            r.errors ? tr().nFailed(r.errors) : null,
                          ]
                            .filter(Boolean)
                            .join(' · ')}
                        </Text>
                        <Text dimColor wrap="wrap">
                          {tr().tokenBreakdown(fmtTokens(r.tokens.input), fmtTokens(r.tokens.output), fmtTokens(r.tokens.cacheRead), fmtTokens(r.tokens.cacheWrite), fmtTokens(r.narratorTokens))}
                        </Text>
                        {r.files.length > 0 && (
                          <Text wrap="wrap">
                            <Text dimColor>{tr().edited}</Text>
                            {r.files.join(tr().listSep)}
                          </Text>
                        )}
                      </Box>
                    )}
                  </Box>
                )
              })}
            </Box>
          ))}
        </Box>
      )
    }

    const body = tab === 'turn' ? await turnView() : tab === 'changes' ? await changesView() : await historyView()

    return (
      <Box flexDirection="column" gap={1}>
        {header}
        {body}
      </Box>
    )
  })
  // ── 设置面板：每项一排选择按钮，当前值高亮，点一下就保存 ──────────────────────
  on('ui.render', { component: 'Pane', requestId: SETTINGS_PANE }, async ($, e) => {
    const { Box, Text, Button } = $.ui.resolve(e)
    const m = tr()
    const current: Record<SettingField, string> = {
      language: config.language,
      bandMode: config.bandMode,
      narrationOverflow: config.overflow,
      narratorMode: config.mode,
      narratorIntervalSeconds: String(config.minGapMs / 1000),
      narratorMaterialChars: String(config.materialStep),
    }
    const resolved = m.langName[m.lang]
    const pending = await read($, pendingSettingAtom)

    return (
      <Box flexDirection="column" gap={1}>
        <Text bold>{m.settingsTitle}</Text>
        {SETTING_FIELDS.map(({ field, choices }) => {
          const meta = m.fields[field]!
          const isSaving = pending?.field === field
          const selected = isSaving ? pending.value : current[field]
          return (
            <Box key={`setting-${field}`} flexDirection="column">
              <Text>
                <Text bold>{meta.title}</Text>
                {isSaving && <Text dimColor>{`  ${m.settingSaving}`}</Text>}
              </Text>
              <Text dimColor wrap="wrap">
                {meta.desc}
              </Text>
              <Box flexDirection="row" gap={1} flexWrap="wrap">
                {choices.map(choice => {
                  const value = String(choice)
                  return (
                    <Button
                      key={`set-${field}-${value}`}
                      label={meta.choice(value, resolved)}
                      variant={selected === value ? 'primary' : 'secondary'}
                      onPress={() => (selected === value ? undefined : void saveSetting($, field, choice))}
                    />
                  )
                })}
              </Box>
            </Box>
          )
        })}
        <Text dimColor wrap="wrap">
          {m.settingsNote}
        </Text>
      </Box>
    )
  })
}

files.hooks/lib.ts:
// 工作台的纯函数：配色、格式化、图标、git 输出解析、提示词。
// 这里不碰 $（引擎只允许 $ 在入口文件里流转），入口文件 register.tsx 调用它们。

import type { GitFile, TokenTally, TurnRecord } from '../types'
import type { Lang } from './i18n'
import { tr } from './i18n'

// ── 配色：Claude 品牌色 + 中间调辅助色，浅色和深色背景上都看得清 ──────────────
export const CLAY = '#D97757' // Claude 的陶土橙
export const CLAY_MUTED = '#B5836B' // 结束后的柔和橙棕
export const STONE = '#8F8A80' // 暖灰
export const SKY = '#6A9BCC'
export const OLIVE = '#788C5D'
export const FIG = '#C46686'
export const CLOUD = '#B0AEA5'
export const AMBER = '#D4A27F'
export const ALERT = '#BF4D43'
export const IDLE = STONE

export const ZERO: TokenTally = { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 }

// ── 格式化 ────────────────────────────────────────────────────────────────
export function duration(ms: number): string {
  const s = Math.max(0, Math.round(ms / 1000))
  return s < 60 ? `${s}s` : `${Math.floor(s / 60)}m${String(s % 60).padStart(2, '0')}s`
}

export function stepTime(ms: number): string {
  return ms < 1000 ? `${ms}ms` : duration(ms)
}

export function fmtTokens(n: number): string {
  if (n < 1000) return String(n)
  if (n < 1_000_000) return `${(n / 1000).toFixed(n < 10_000 ? 1 : 0)}k`
  return `${(n / 1_000_000).toFixed(2)}M`
}

export function clockTime(ms: number): string {
  const d = new Date(ms)
  return `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`
}

export function clip(text: string, max: number): string {
  return text.length > max ? `${text.slice(0, max - 1)}…` : text
}

// ── 工具调用 ──────────────────────────────────────────────────────────────
// 完整的命令或主要参数（展开、复制、填入输入框时用）
export function detailOf(args: Record<string, unknown>): string {
  const pick = (k: string) => (typeof args[k] === 'string' ? (args[k] as string) : '')
  const raw =
    pick('command') ||
    pick('file_path') ||
    pick('notebook_path') ||
    pick('path') ||
    pick('pattern') ||
    pick('url') ||
    pick('query') ||
    pick('description') ||
    pick('prompt') ||
    pick('skill')
  return clip(raw.trim(), 2000)
}

export function labelOf(args: Record<string, unknown>): string {
  const pick = (k: string) => (typeof args[k] === 'string' ? (args[k] as string) : '')
  const path = pick('file_path') || pick('notebook_path') || pick('path')
  const raw =
    pick('command') ||
    path ||
    pick('pattern') ||
    pick('url') ||
    pick('query') ||
    pick('description') ||
    pick('prompt') ||
    pick('skill')
  return clip(raw.replace(/\s+/g, ' ').trim(), 120)
}

// 编辑类工具改的是哪个文件
export function editedPath(tool: string, args: Record<string, unknown>): string | null {
  if (!/^(Edit|MultiEdit|Write|NotebookEdit)$/.test(tool)) return null
  const p = args['file_path'] ?? args['notebook_path']
  return typeof p === 'string' ? p : null
}

export function shortTool(tool: string): string {
  return tool.startsWith('mcp__') ? (tool.split('__').pop() ?? tool) : tool
}

export function shortLabel(label: string, max = 36): string {
  const base = label.includes('/') && !label.includes(' ') ? (label.split('/').pop() ?? label) : label
  return clip(base, max)
}

export function toolColor(tool: string): string {
  if (/^(Read|Grep|Glob|LS)$/.test(tool)) return SKY
  if (/^(Bash|BashOutput|KillShell)$/.test(tool)) return CLAY
  if (/^(Edit|MultiEdit|Write|NotebookEdit)$/.test(tool)) return OLIVE
  if (/^Web/.test(tool)) return '#9C87C4'
  if (/^(Agent|Task)$/.test(tool)) return FIG
  return STONE
}

// 工具失败时的原因：拒绝理由，或输出的第一行
export function errorOf(ran: { deny?: string; isError?: boolean; text?: string }): string | null {
  if (ran.deny !== undefined) return clip(tr().denied(ran.deny), 200)
  if (ran.isError !== true) return null
  const first = (ran.text ?? '').split('\n').find(l => l.trim()) ?? ''
  return clip(first.trim(), 200) || tr().failed
}

// ── 旁白 ──────────────────────────────────────────────────────────────────
const NARRATION_MAX = 120

export function oneLine(text: string): string {
  const line = text
    .replace(/\s+/g, ' ')
    .replace(/^["“「]|["”」]$/g, '')
    .replace(/[。.]$/, '')
    .trim()
  return clip(line, NARRATION_MAX) // 保留全文，只防极端长度；显示时再按 narrationOverflow 处理
}

// ── token 图标：16px 高的线性小图标，桌面端画 SVG，终端退回 Unicode 符号 ──────────
export const ICON_H = 14

function iconSvg(width: number, body: string): string {
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="16" viewBox="0 0 ${width} 16" fill="none" stroke-linecap="round" stroke-linejoin="round">${body}</svg>`
}

const cylinder = (c: string) =>
  `<ellipse cx="6.5" cy="4" rx="5" ry="2" stroke="${c}" stroke-width="1.5"/>` +
  `<path d="M1.5 4v8c0 1.1 2.2 2 5 2s5-.9 5-2V4M1.5 8c0 1.1 2.2 2 5 2s5-.9 5-2" stroke="${c}" stroke-width="1.5"/>`

export const ICONS = {
  input: (c: string) => iconSvg(16, `<path d="M8 13.5V3M3.5 7.5 8 3l4.5 4.5" stroke="${c}" stroke-width="2"/>`),
  output: (c: string) => iconSvg(16, `<path d="M8 2.5V13M3.5 8.5 8 13l4.5-4.5" stroke="${c}" stroke-width="2"/>`),
  cacheRead: (c: string) => iconSvg(22, cylinder(c) + `<path d="M18 13.5V5M15 8l3-3 3 3" stroke="${c}" stroke-width="1.6"/>`),
  cacheWrite: (c: string) => iconSvg(22, cylinder(c) + `<path d="M18 4.5V13M15 10l3 3 3-3" stroke="${c}" stroke-width="1.6"/>`),
  narrator: (c: string) =>
    iconSvg(16, `<path d="M3 3.5h10a1.5 1.5 0 0 1 1.5 1.5v5A1.5 1.5 0 0 1 13 11.5H8l-3.5 2.5v-2.5H3A1.5 1.5 0 0 1 1.5 10V5A1.5 1.5 0 0 1 3 3.5z" stroke="${c}" stroke-width="1.5"/>`),
  hit: (c: string) =>
    iconSvg(16, `<circle cx="8" cy="8" r="6.5" stroke="${c}" stroke-width="1.5"/><circle cx="8" cy="8" r="3.5" stroke="${c}" stroke-width="1.5"/><circle cx="8" cy="8" r="1.2" fill="${c}"/>`),
  cost: (c: string) =>
    iconSvg(16, `<circle cx="8" cy="8" r="6.5" stroke="${c}" stroke-width="1.5"/><text x="8" y="11.6" fill="${c}" font-size="10" font-weight="700" text-anchor="middle" font-family="-apple-system, 'Segoe UI', sans-serif">$</text>`),
  context: (c: string) =>
    iconSvg(16, `<rect x="1.5" y="2.5" width="13" height="11" rx="2" stroke="${c}" stroke-width="1.5"/><path d="M1.5 6h13" stroke="${c}" stroke-width="1.5"/>`),
}

export type IconKind = keyof typeof ICONS

export const GLYPHS: Record<IconKind, string> = {
  input: '↑',
  output: '↓',
  cacheRead: '≡↑',
  cacheWrite: '≡↓',
  narrator: '❝',
  hit: '◎',
  cost: '$',
  context: '▤',
}

// 终端里一个字符占几格：中日韩文字和全角符号占两格
export function cellWidth(text: string): number {
  let n = 0
  for (const ch of text) n += /[\u1100-\u115f\u2e80-\ua4cf\uac00-\ud7a3\uf900-\ufaff\ufe30-\ufe4f\uff00-\uff60\uffe0-\uffe6]/.test(ch) ? 2 : 1
  return n
}

// 工作中的三个圆点：动画写在 SVG 里（SMIL），由图片自己播放，插件不用为它重绘。
// 横幅一重绘按钮就会被替换，点击容易落空，所以周期性的动画不能靠重绘来驱动
export const DOTS_W = 30
export const DOTS_H = 10

export function dotsSvg(on: string, off: string): string {
  const dot = (cx: number, begin: number) =>
    `<circle cx="${cx}" cy="5" r="3.5" fill="${off}">` +
    `<animate attributeName="fill" values="${off};${on};${on};${off}" keyTimes="0;0.2;0.6;1" dur="1.5s" begin="${begin}s" repeatCount="indefinite"/>` +
    `</circle>`
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${DOTS_W}" height="${DOTS_H}" viewBox="0 0 ${DOTS_W} ${DOTS_H}">${dot(5, 0)}${dot(15, 0.3)}${dot(25, 0.6)}</svg>`
}

// 「滚动」模式：把旁白画成一张自带动画的 SVG（SMIL），放不下时左右来回滚，两头各停一下。
// 不靠重绘驱动，所以不会影响按钮点击。textLength 把文字压到估算宽度上，估算和实际画出来的一致
export const MARQUEE_H = 20

function textPixels(text: string, fontSize: number): number {
  let w = 0
  for (const ch of text) w += cellWidth(ch) === 2 ? fontSize : fontSize * 0.56
  return Math.ceil(w)
}

export function marqueeSvg(text: string, color: string, isBold: boolean, width: number): string {
  const fontSize = 14
  const textW = textPixels(text, fontSize)
  const font = `font-family="-apple-system, 'PingFang SC', 'Segoe UI', sans-serif" font-size="${fontSize}" font-weight="${isBold ? 600 : 400}"`
  const escaped = text.replace(/[&<>"']/g, c => `&#${c.charCodeAt(0)};`)
  const fits = textW <= width
  const dist = textW - width + 16
  const dur = Math.max(6, Math.round(dist / 30) + 4) // 约 30px/s，再加两头的停顿
  const motion = fits
    ? ''
    : `<animateTransform attributeName="transform" type="translate" values="0 0;0 0;${-dist} 0;${-dist} 0;0 0" keyTimes="0;0.2;0.7;0.9;1" dur="${dur}s" repeatCount="indefinite"/>`
  return (
    `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${MARQUEE_H}" viewBox="0 0 ${width} ${MARQUEE_H}">` +
    `<text x="0" y="15" fill="${color}" ${font} textLength="${textW}" lengthAdjust="spacingAndGlyphs">${escaped}${motion}</text>` +
    `</svg>`
  )
}

export const iconWidth = (kind: IconKind) => (kind.startsWith('cache') ? (ICON_H * 22) / 16 : ICON_H)

// ── git ───────────────────────────────────────────────────────────────────
// `git status --porcelain=v1` 的一行："XY path" 或 "R  old -> new"
export function parseStatus(stdout: string): GitFile[] {
  return stdout
    .split('\n')
    .filter(l => l.length > 3)
    .map(l => {
      const xy = l.slice(0, 2)
      const rest = l.slice(3)
      const path = rest.includes(' -> ') ? rest.split(' -> ').pop()! : rest
      const status = xy === '??' ? '??' : (xy.trim()[0] ?? 'M')
      return { path: path.replace(/^"|"$/g, ''), status, added: null, removed: null }
    })
}

// `git diff --numstat` 的一行："added\tremoved\tpath"（二进制文件是 "-\t-\tpath"）
export function mergeNumstat(files: GitFile[], stdout: string): GitFile[] {
  const stats = new Map<string, [number | null, number | null]>()
  for (const l of stdout.split('\n')) {
    const [a, r, ...p] = l.split('\t')
    if (!p.length) continue
    const path = p.join('\t').replace(/^.*=> /, '').replace(/[{}]/g, '')
    stats.set(path, [a === '-' ? null : Number(a), r === '-' ? null : Number(r)])
  }
  return files.map(f => {
    const s = stats.get(f.path)
    return s ? { ...f, added: s[0], removed: s[1] } : f
  })
}

export function statusColor(status: string): string {
  if (status === '??' || status === 'A') return OLIVE
  if (status === 'D') return ALERT
  if (status === 'R') return SKY
  return AMBER
}

export function splitPath(path: string): { dir: string; name: string } {
  const i = path.lastIndexOf('/')
  return i < 0 ? { dir: '', name: path } : { dir: path.slice(0, i + 1), name: path.slice(i + 1) }
}

// ── 配置（plugin.json 的 userConfig）──────────────────────────────────────────
export type NarratorMode = 'full' | 'lite' | 'off'

export type BandMode = 'band' | 'status' | 'off'

export type Overflow = 'truncate' | 'wrap' | 'scroll'

export type NarratorConfig = {
  mode: NarratorMode
  bandMode: BandMode
  overflow: Overflow
  language: Lang | 'auto'
  minGapMs: number
  materialStep: number
}

function numberOption(value: unknown, min: number, max: number, fallback: number): number {
  const n = typeof value === 'number' ? value : typeof value === 'string' ? Number(value) : NaN
  return Number.isFinite(n) ? Math.min(max, Math.max(min, n)) : fallback
}

export function narratorConfig(options: Readonly<Record<string, unknown>>): NarratorConfig {
  const mode = options['narratorMode']
  const band = options['bandMode']
  return {
    mode: mode === 'lite' || mode === 'off' ? mode : 'full',
    bandMode: band === 'status' || band === 'off' ? band : 'band',
    language: options['language'] === 'en' || options['language'] === 'zh' ? options['language'] : 'auto',
    overflow: options['narrationOverflow'] === 'wrap' || options['narrationOverflow'] === 'scroll' ? options['narrationOverflow'] : 'truncate',
    minGapMs: numberOption(options['narratorIntervalSeconds'], 3, 120, 8) * 1000,
    materialStep: numberOption(options['narratorMaterialChars'], 100, 5000, 400),
  }
}

// ── 设置面板：每个配置项给出可选值（数字项给几个常用档位） ─────────────────────────
export const SETTING_FIELDS = [
  { field: 'language', choices: ['auto', 'en', 'zh'] },
  { field: 'bandMode', choices: ['band', 'status', 'off'] },
  { field: 'narrationOverflow', choices: ['truncate', 'wrap', 'scroll'] },
  { field: 'narratorMode', choices: ['full', 'lite', 'off'] },
  { field: 'narratorIntervalSeconds', choices: [5, 8, 15, 30, 60] },
  { field: 'narratorMaterialChars', choices: [200, 400, 800, 1600] },
] as const

export type SettingField = (typeof SETTING_FIELDS)[number]['field']

// `/config` 里插件配置项的键是 `<plugin>.<field>`，开发时插件名可能带 `@inline` 之类的后缀
export function isOwnConfigKey(key: string, field: string): boolean {
  return /^workbench(@[^.]+)?\./.test(key) && key.endsWith(`.${field}`)
}

// ── 历史 ──────────────────────────────────────────────────────────────────
export const tokenTotal = (t: TokenTally) => t.input + t.output + t.cacheRead + t.cacheWrite

export function money(usd: number): string {
  return `$${usd.toFixed(usd < 1 ? 3 : 2)}`
}

function dayKey(ms: number): string {
  const d = new Date(ms)
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`
}

export function dayLabel(ms: number, now = Date.now()): string {
  if (dayKey(ms) === dayKey(now)) return tr().today
  if (dayKey(ms) === dayKey(now - 86_400_000)) return tr().yesterday
  const d = new Date(ms)
  return tr().monthDay(d.getMonth() + 1, d.getDate())
}

// 按天分组，组内和组间都是新的在前
export function groupByDay(records: readonly TurnRecord[]): { label: string; items: TurnRecord[] }[] {
  const groups: { key: string; label: string; items: TurnRecord[] }[] = []
  for (const r of [...records].sort((a, b) => b.startedAt - a.startedAt)) {
    const key = dayKey(r.startedAt)
    const last = groups[groups.length - 1]
    if (last && last.key === key) last.items.push(r)
    else groups.push({ key, label: dayLabel(r.startedAt), items: [r] })
  }
  return groups
}

export function recordMeta(r: TurnRecord): string {
  return [tr().nSteps(r.steps), duration(r.endedAt - r.startedAt), r.costUsd !== null ? money(r.costUsd) : null].filter(Boolean).join(' · ')
}

// 「复制今天的工作记录」：一行一轮的 Markdown
export function dayLog(records: readonly TurnRecord[], now = Date.now()): string {
  const today = records.filter(r => dayKey(r.startedAt) === dayKey(now)).sort((a, b) => a.startedAt - b.startedAt)
  const lines = today.map(r => `- ${clockTime(r.startedAt)} ${r.project ? `[${r.project}] ` : ''}${r.summary}（${recordMeta(r)}）`)
  return [tr().dayLogTitle(dayKey(now)), '', ...lines].join('\n')
}

// 最近若干轮的花费柱状图（没有花费数据时改用 token 总量）。静态 SVG：只在新增记录时变化
export function usageChart(records: readonly TurnRecord[], width: number, height: number): string {
  const list = [...records].sort((a, b) => a.startedAt - b.startedAt).slice(-24)
  const useCost = list.every(r => r.costUsd !== null)
  const values = list.map(r => (useCost ? (r.costUsd ?? 0) : tokenTotal(r.tokens)))
  const max = Math.max(...values, useCost ? 0.001 : 1)
  const top = 16
  const gap = 4
  const barW = list.length ? Math.max(4, Math.min(28, (width - gap * (list.length - 1)) / list.length)) : 0
  const bars = list
    .map((r, i) => {
      const h = Math.max(2, ((values[i] ?? 0) / max) * (height - top - 2))
      const x = i * (barW + gap)
      const color = i === list.length - 1 ? CLAY : r.errors > 0 ? AMBER : CLAY_MUTED
      return `<rect x="${x.toFixed(1)}" y="${(height - h).toFixed(1)}" width="${barW.toFixed(1)}" height="${h.toFixed(1)}" rx="2" fill="${color}"/>`
    })
    .join('')
  const label = useCost ? tr().chartMaxCost(money(max)) : tr().chartMaxTokens(fmtTokens(max))
  return (
    `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">` +
    `<text x="0" y="11" font-size="11" fill="${STONE}" font-family="-apple-system, 'Segoe UI', sans-serif">${label}</text>` +
    `<line x1="0" y1="${height - 0.5}" x2="${width}" y2="${height - 0.5}" stroke="${CLOUD}" stroke-width="1"/>` +
    bars +
    `</svg>`
  )
}

